from ute_common_config.config import Config
from ute_common_validator.validator import IsIpAddress, Or, IsInstance


class TrsSchemas(Config):
    """Transport schema base class"""
    IP_VALIDATOR = IsIpAddress()

    def __setitem__(self, key, value):
        if key in self._attributes:
            self._set_attr(key, value, Or(TrsSchemas.IP_VALIDATOR, IsInstance(type(None))))


class TrsSchema1(TrsSchemas):
    """Transport schema1 class."""

    IPs = {'enb': '10.0.1.2', 'iphy': '10.0.2.2'}

    def __init__(self):
        super(TrsSchema1, self).__init__()
        self._set_attr("enb", TrsSchema1.IPs['enb'], TrsSchemas.IP_VALIDATOR)
        self._set_attr("iphy", TrsSchema1.IPs['iphy'], TrsSchemas.IP_VALIDATOR)


